const BASIS = {
  "document.read": "A",
  "document.analyze": "A",
  "document.file": "B",
  "document.move": "B",
  "task.create": "B",
  "task.update": "B",
  "crm.update_record": "B",
  "draft.create": "B",
  "report.write": "B",
  "mail.send": "C",
  "message.send": "C",
  "test.record_approved_action": "C"
};
const OVERRIDES = {
  arbeitgeber_visolva: { "mail.send": "C", "crm.update_record": "B" }
};
const RANG = { A: 1, B: 2, C: 3 };
const KONTEXTE = ["privat", "arbeitgeber_visolva"];

const ergebnis = [];
for (const item of $input.all()) {
  const kontext = item.json.context_id;
  const art = item.json.action_type;
  if (KONTEXTE.indexOf(kontext) === -1) {
    throw new Error("action_classify_invalid_input: context_id nicht im Register");
  }
  if (!art) {
    throw new Error("action_classify_invalid_input: action_type fehlt");
  }

  const bekannt = Object.prototype.hasOwnProperty.call(BASIS, art);
  const ausRegister = bekannt ? BASIS[art] : "C";
  const quelle = bekannt ? "tool_registry" : "unknown_action_type_fail_closed";

  const kontextRegeln = Object.prototype.hasOwnProperty.call(OVERRIDES, kontext) ? OVERRIDES[kontext] : {};
  const ausOverride = Object.prototype.hasOwnProperty.call(kontextRegeln, art) ? kontextRegeln[art] : null;

  let klasse = ausRegister;
  let herkunft = quelle;
  if (ausOverride && RANG[ausOverride] > RANG[klasse]) {
    klasse = ausOverride;
    herkunft = "context_override";
  }
  if (item.json.external_effect === true && RANG["C"] > RANG[klasse]) {
    klasse = "C";
    herkunft = "external_effect";
  }

  ergebnis.push({ json: {
    risk_class: klasse,
    risk_class_source: herkunft,
    approval_required: klasse === "C",
    max_autonomous_class: "B",
    action_type: art,
    tool_id: item.json.tool_id || null,
    context_id: kontext,
    trace_id: item.json.trace_id || null
  } });
}
return ergebnis;
